#include <WiFi.h>

const char* ssid = "REMOTE-TV-TEST";
const char* password = "Remote123";

void setup() {
  Serial.begin(115200);

  WiFi.mode(WIFI_AP);

  bool success = WiFi.softAP(ssid, password);

  if (success) {
    Serial.println("ESP32 WiFi started!");
    Serial.print("WiFi name: ");
    Serial.println(ssid);
    Serial.print("IP address: ");
    Serial.println(WiFi.softAPIP());
  } else {
    Serial.println("WiFi failed to start.");
  }
}

void loop() {
  delay(1000);
}
